#!/usr/bin/env python3
import argparse,json
from pathlib import Path
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--data',required=True);ap.add_argument('--output',required=True);a=ap.parse_args();d=Path(a.data)
 n=json.loads((d/'nodes.json').read_text()) if (d/'nodes.json').exists() else []; e=json.loads((d/'edges.json').read_text()) if (d/'edges.json').exists() else []; au=json.loads((d/'authors.json').read_text()) if (d/'authors.json').exists() else []; w=json.loads((d/'works.json').read_text()) if (d/'works.json').exists() else []
 js=json.dumps({'nodes':n,'edges':e,'authors':au,'works':w},ensure_ascii=False).replace('</','<\\/')
 html='''<!doctype html><meta charset="utf-8"><title>Hinton Academic Tree</title><style>body{margin:0;display:flex;height:100vh;font:14px system-ui}#v{flex:1;background:#f7f9fc}svg{width:100%;height:100%}.edge{stroke:#9aa;fill:none}.node{stroke:#fff;cursor:pointer}.label{text-anchor:middle;font-size:12px}.panel{width:320px;padding:18px;overflow:auto;background:#fff;border-left:1px solid #ddd}.bar{position:absolute;padding:10px}.bar input{padding:7px}</style><div id="v"><div class="bar"><input id="q" placeholder="Search author"></div><svg id="s" viewBox="0 0 1400 900"></svg></div><aside class="panel" id="p"><h2>Select an author</h2></aside><script>const D='''+js+''';const s=document.querySelector('#s'),p=document.querySelector('#p');let pos={};D.nodes.forEach((n,i)=>pos[n.id]={x:100+(i%7)*190,y:100+Math.floor(i/7)*80});D.edges.forEach(e=>{if(pos[e.source_id]&&pos[e.target_id])s.insertAdjacentHTML('beforeend',`<path class=edge d="M${pos[e.source_id].x},${pos[e.source_id].y} C${pos[e.source_id].x+70},${pos[e.source_id].y} ${pos[e.target_id].x-70},${pos[e.target_id].y} ${pos[e.target_id].x},${pos[e.target_id].y}"/>`)});D.nodes.forEach(n=>{let a=D.authors.find(x=>x.node_id===n.id),ws=D.works.filter(w=>(a?.works||[]).includes(w.work_id)),r=8+Math.log1p(ws.length)*5,c=ws.reduce((x,w)=>x+(w.cited_by_count||0),0);s.insertAdjacentHTML('beforeend',`<g onclick="show('${n.id}')"><circle class=node cx=${pos[n.id].x} cy=${pos[n.id].y} r=${r} fill="hsl(${220-Math.min(170,Math.log1p(c)*20)},70%,55%)"/><text class=label x=${pos[n.id].x} y=${pos[n.id].y+r+15}>${n.name}</text></g>`)});function show(id){let n=D.nodes.find(x=>x.id===id),a=D.authors.find(x=>x.node_id===id),ws=D.works.filter(w=>(a?.works||[]).includes(w.work_id));p.innerHTML=`<h2>${n?.name||id}</h2><p>Works: ${ws.length||a?.works?.length||0}</p>`+ws.slice(0,100).map(w=>`<div style="border-top:1px solid #ddd;padding:7px"><b>${w.title}</b><br>${w.publication_year||''} · cited ${w.cited_by_count||0}</div>`).join('')}document.querySelector('#q').oninput=e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('g').forEach((g,i)=>g.style.opacity=D.nodes[i].name.toLowerCase().includes(q)?1:.12)}</script>'''
 Path(a.output).write_text(html)
if __name__=='__main__':main()
